const { spawn } = require\('child_process'\);
const cli = spawn\('npm', ['run', 'cli'], { stdio: ['pipe', 'pipe', 'inherit'] }\);

let output = '';
cli.stdout.on\('data', \(data\) => { output += data.toString\(\); }\);

const commands = [
  'status',
  'upgrade barkeep 5',
  'status',
  'tick 1000',
  'status',
  'upgrade barkeep 10',
  'status',
  'income',
  'save test_save.json',
  'exit'
];

let i = 0;
const sendNext = \(\) => {
  if \(i < commands.length\) {
    setTimeout\(\(\) => {
      cli.stdin.write\(commands[i++] + '\\\\n'\);
      sendNext\(\);
    }, 300\);
  } else {
    setTimeout\(\(\) => {
      console.log\('\\\\n' + '='.repeat\(60\)\);
      console.log\(output\);
      cli.kill\(\);
    }, 500\);
  }
};
sendNext\(\);
